import re
from decimal import Decimal

class InsufficientFunds(Exception):
    pass

class Ledger:
    _amount_pattern = re.compile(r"[0-9]+(?:\.[0-9]{1,2})?")
    _fee = Decimal("1.50")
    _quant = Decimal("0.01")

    def __init__(self, overdraft_limit="0.00"):
        self._overdraft_limit = self._parse(overdraft_limit)
        self._balance = Decimal("0.00")
        self._history = []

    def _parse(self, value):
        if not isinstance(value, str):
            raise TypeError("amount must be a string")
        if not self._amount_pattern.fullmatch(value):
            raise ValueError("invalid amount format")
        return Decimal(value)

    def _check_amount(self, amount):
        decimal = self._parse(amount)
        if decimal == 0:
            raise ValueError("amount must be non-zero")
        return decimal

    def _fmt(self, value):
        return str(value.quantize(self._quant))

    def deposit(self, amount):
        decimal = self._check_amount(amount)
        self._balance += decimal
        self._history.append(("deposit", self._fmt(decimal)))

    def withdraw(self, amount):
        decimal = self._check_amount(amount)
        new_balance = self._balance - decimal
        if new_balance < -self._overdraft_limit:
            raise InsufficientFunds("insufficient funds")
        self._balance = new_balance
        self._history.append(("withdraw", self._fmt(decimal)))
        if self._balance < 0:
            self._balance -= self._fee
            self._history.append(("fee", self._fmt(self._fee)))

    def balance(self):
        return self._fmt(self._balance)

    def history(self):
        return list(self._history)
