import heapq


def _validate(meetings, k):
    if type(k) is not int or k < 1:
        raise ValueError("k must be an int >= 1")
    if not isinstance(meetings, list):
        raise ValueError("meetings must be a list")
    for item in meetings:
        if not isinstance(item, (tuple, list)) or len(item) != 2:
            raise ValueError("each meeting must be a (start, end) pair")
        start, end = item
        if type(start) is not int or type(end) is not int:
            raise ValueError("start and end must be ints")
        if start >= end:
            raise ValueError("start must be less than end")


def assign_rooms(meetings, k):
    _validate(meetings, k)
    n = len(meetings)
    if n == 0:
        return []

    order = sorted(range(n), key=lambda i: (meetings[i][0], i))

    available = list(range(k))
    heapq.heapify(available)
    busy = []
    result = [None] * n

    for idx in order:
        start, end = meetings[idx]
        duration = end - start

        while busy and busy[0][0] <= start:
            _, room = heapq.heappop(busy)
            heapq.heappush(available, room)

        if available:
            room = heapq.heappop(available)
            actual_start = start
        else:
            actual_start, room = heapq.heappop(busy)

        actual_end = actual_start + duration
        result[idx] = (room, actual_start, actual_end)
        heapq.heappush(busy, (actual_end, room))

    return result


def busiest_room(meetings, k):
    assignments = assign_rooms(meetings, k)
    if not assignments:
        return 0

    counts = [0] * k
    for room, _, _ in assignments:
        counts[room] += 1

    best = 0
    for i in range(1, k):
        if counts[i] > counts[best]:
            best = i

    return best
