import bisect
from typing import Iterable, List, Sequence, Tuple, Union

Number = Union[int, float]
Interval = Sequence[Number]


def _normalize(intervals: Iterable[Interval]) -> List[Tuple[Number, Number]]:
    normalized: List[Tuple[Number, Number]] = []
    for iv in intervals:
        start, end = iv
        if start > end:
            raise ValueError("Interval start must not be greater than end")
        if start != end:
            normalized.append((start, end))
    normalized.sort()
    return normalized


def merge(intervals: Iterable[Interval]) -> List[Tuple[Number, Number]]:
    normalized = _normalize(intervals)
    if not normalized:
        return []
    merged: List[Tuple[Number, Number]] = [normalized[0]]
    for start, end in normalized[1:]:
        last_start, last_end = merged[-1]
        if start <= last_end:
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))
    return merged


def subtract(a: Iterable[Interval], b: Iterable[Interval]) -> List[Tuple[Number, Number]]:
    a_merged = merge(a)
    if not a_merged:
        return []
    b_merged = merge(b)
    if not b_merged:
        return list(a_merged)

    b_ends = [iv[1] for iv in b_merged]
    result: List[Tuple[Number, Number]] = []

    for a_start, a_end in a_merged:
        i = bisect.bisect_right(b_ends, a_start)
        cur = a_start
        while i < len(b_merged) and b_merged[i][0] < a_end:
            b_start, b_end = b_merged[i]
            if b_start > cur:
                result.append((cur, b_start))
            cur = max(cur, b_end)
            if cur >= a_end:
                break
            i += 1
        if cur < a_end:
            result.append((cur, a_end))

    return result


def total_length(intervals: Iterable[Interval]) -> Number:
    return sum(end - start for start, end in merge(intervals))
