def render(template: str, values: dict) -> str:
    _MISSING = object()

    def _format_value(value):
        if value is True:
            return "true"
        if value is False:
            return "false"
        return str(value)

    def _valid_key(key: str) -> bool:
        if not key:
            return False
        start = 0
        n = len(key)
        while True:
            dot = key.find('.', start)
            seg_end = n if dot == -1 else dot
            if start >= seg_end:
                return False
            ch = key[start]
            if not (('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or ch == '_'):
                return False
            for idx in range(start + 1, seg_end):
                ch = key[idx]
                if not (('a' <= ch <= 'z') or ('A' <= ch <= 'Z') or
                        ('0' <= ch <= '9') or ch == '_'):
                    return False
            if dot == -1:
                return True
            start = dot + 1

    def _lookup(key: str):
        cur = values
        start = 0
        while True:
            dot = key.find('.', start)
            if dot == -1:
                part = key[start:]
                if not isinstance(cur, dict) or part not in cur:
                    return _MISSING
                value = cur[part]
                if value is None:
                    return _MISSING
                return value
            part = key[start:dot]
            if not isinstance(cur, dict) or part not in cur:
                return _MISSING
            cur = cur[part]
            start = dot + 1

    def _resolve(content: str) -> str:
        sep = content.find('|')
        if sep == -1:
            key_raw = content
            default = None
        else:
            key_raw = content[:sep]
            default = content[sep + 1:].strip(' ')
        key = key_raw.strip(' ')
        if not _valid_key(key):
            raise ValueError(f"bad key: {key}")
        value = _lookup(key)
        if value is _MISSING:
            if default is not None:
                return default
            raise KeyError(f"missing: {key}")
        return _format_value(value)

    t = template
    n = len(t)
    out = []
    i = 0
    literal_start = 0

    while i < n:
        ch = t[i]
        if ch == '\\':
            if i + 1 < n and t[i + 1] == '\\':
                if i > literal_start:
                    out.append(t[literal_start:i])
                out.append('\\')
                i += 2
                literal_start = i
            elif i + 2 < n and t[i + 1] == '{' and t[i + 2] == '{':
                if i > literal_start:
                    out.append(t[literal_start:i])
                out.append('{{')
                i += 3
                literal_start = i
            else:
                i += 1
        elif ch == '{' and i + 1 < n and t[i + 1] == '{':
            if i > literal_start:
                out.append(t[literal_start:i])
            end = t.find('}}', i + 2)
            if end == -1:
                raise ValueError(f"unclosed placeholder at {i}")
            out.append(_resolve(t[i + 2:end]))
            i = end + 2
            literal_start = i
        else:
            i += 1

    if i > literal_start:
        out.append(t[literal_start:i])
    return ''.join(out)
