def parse_ini(text: str) -> dict[str, dict[str, str]]:
    result: dict[str, dict[str, str]] = {}
    current_section = ""
    current_key: str | None = None

    lines = [line.removesuffix("\r") for line in text.split("\n")]

    for n, raw_line in enumerate(lines, start=1):
        stripped = raw_line.strip()

        # Rule 1: blank or whitespace-only line
        if not stripped:
            current_key = None
            continue

        # Rule 2: comment line (first non-whitespace is ';' or '#')
        if stripped[0] in ";#":
            continue

        # Rule 3: continuation line (starts with space or tab)
        if raw_line[0] in " \t":
            if current_key is None:
                raise ValueError(f"line {n}: continuation line without a key")
            text_part = stripped
            old_value = result[current_section][current_key]
            if old_value:
                result[current_section][current_key] = old_value + " " + text_part
            else:
                result[current_section][current_key] = text_part
            continue

        # Rule 4: section header
        if stripped.startswith("[") and stripped.endswith("]"):
            section_name = stripped[1:-1].strip().lower()
            current_section = section_name
            result.setdefault(current_section, {})
            current_key = None
            continue

        # Rule 5: key/value line
        if "=" not in raw_line:
            raise ValueError(f"line {n}: missing '=' in key line")
        key_part, value_part = raw_line.split("=", 1)
        key = key_part.strip().lower()
        value = value_part.strip()
        if not key:
            raise ValueError(f"line {n}: empty key")

        result.setdefault(current_section, {})
        if key in result[current_section]:
            raise ValueError(f"duplicate key {key!r} in section {current_section!r}")

        result[current_section][key] = value
        current_key = key

    # Rule 6: strip one pair of surrounding double quotes
    for section in result.values():
        for k, v in section.items():
            if len(v) >= 2 and v.startswith('"') and v.endswith('"'):
                section[k] = v[1:-1]

    return result
