import copy
from typing import Any, List

__all__ = ["resolve", "set_value", "escape_token"]


def _decode_pointer(pointer: str) -> List[str]:
    if pointer == "":
        return []
    if not pointer.startswith("/"):
        raise ValueError("Non-empty JSON pointer must start with '/'")
    decoded_tokens: List[str] = []
    for raw in pointer.split("/")[1:]:
        out: List[str] = []
        i = 0
        n = len(raw)
        while i < n:
            ch = raw[i]
            if ch == "~":
                if i + 1 >= n:
                    raise ValueError("Trailing '~' in pointer token")
                nxt = raw[i + 1]
                if nxt == "0":
                    out.append("~")
                elif nxt == "1":
                    out.append("/")
                else:
                    raise ValueError("Invalid '~' escape in pointer token")
                i += 2
            else:
                out.append(ch)
                i += 1
        decoded_tokens.append("".join(out))
    return decoded_tokens


def _list_index(token: str, lst: list) -> int:
    if token == "-":
        raise KeyError(token)
    if not token.isdigit() or (token[0] == "0" and len(token) > 1):
        raise KeyError(token)
    idx = int(token)
    if idx >= len(lst):
        raise KeyError(token)
    return idx


def _list_index_or_append(token: str, lst: list) -> int | None:
    if token == "-" or token == str(len(lst)):
        return None
    if not token.isdigit() or (token[0] == "0" and len(token) > 1):
        raise KeyError(token)
    idx = int(token)
    if idx >= len(lst):
        raise KeyError(token)
    return idx


def resolve(doc: Any, pointer: str) -> Any:
    tokens = _decode_pointer(pointer)
    current = doc
    for token in tokens:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            current = current[_list_index(token, current)]
        else:
            raise KeyError(token)
    return current


def set_value(doc: Any, pointer: str, value: Any) -> Any:
    tokens = _decode_pointer(pointer)
    if not tokens:
        return value
    new_doc = copy.deepcopy(doc)
    current = new_doc
    for token in tokens[:-1]:
        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            current = current[_list_index(token, current)]
        else:
            raise KeyError(token)
    last = tokens[-1]
    if isinstance(current, dict):
        current[last] = value
    elif isinstance(current, list):
        idx = _list_index_or_append(last, current)
        if idx is None:
            current.append(value)
        else:
            current[idx] = value
    else:
        raise KeyError(last)
    return new_doc


def escape_token(token: str) -> str:
    return token.replace("~", "~0").replace("/", "~1")
