def parse_port(s: str) -> int:
    original = str(s)
    t = original.strip()

    if not t:
        raise ValueError("invalid port: " + original)

    for ch in t:
        if ch < "0" or ch > "9":
            raise ValueError("invalid port: " + original)

    if len(t) > 1 and t[0] == "0":
        raise ValueError("invalid port: " + original)

    n = int(t)
    if n < 1 or n > 65535:
        raise ValueError("port out of range: " + original)

    return n
