def wrap_text(text, width):
    if not isinstance(width, int) or width < 2:
        raise ValueError("width must be an integer >= 2")

    words = text.split()
    if not words:
        return []

    lines = []
    current = ""

    for word in words:
        word_len = len(word)

        if word_len > width:
            if current:
                lines.append(current)
                current = ""

            while len(word) > width:
                chunk = word[:width - 1]
                lines.append(chunk + "-")
                word = word[width - 1:]

            current = word
        else:
            if current == "":
                current = word
            elif len(current) + 1 + word_len <= width:
                current = current + " " + word
            else:
                lines.append(current)
                current = word

    if current:
        lines.append(current)

    return lines
