import collections
import math


def _validate_limit(limit):
    if isinstance(limit, bool) or not isinstance(limit, (int, float)):
        raise ValueError("limit must be an int or float")
    if isinstance(limit, float) and math.isnan(limit):
        raise ValueError("limit must not be NaN")
    if limit < 0:
        raise ValueError("limit must be non-negative")


def _validate_element(x):
    if isinstance(x, bool) or not isinstance(x, (int, float)):
        raise TypeError("values must contain ints or floats only")
    if isinstance(x, float) and math.isnan(x):
        raise ValueError("values must not contain NaN")


def _calm_windows(values, limit):
    _validate_limit(limit)
    n = len(values)
    max_d = collections.deque()
    min_d = collections.deque()
    r = 0
    for l in range(n):
        while r < n:
            x = values[r]
            _validate_element(x)
            while max_d and values[max_d[-1]] <= x:
                max_d.pop()
            max_d.append(r)
            while min_d and values[min_d[-1]] >= x:
                min_d.pop()
            min_d.append(r)
            cur_max = values[max_d[0]]
            cur_min = values[min_d[0]]
            if cur_max == cur_min or cur_max - cur_min <= limit:
                r += 1
            else:
                if max_d[-1] == r:
                    max_d.pop()
                if min_d[-1] == r:
                    min_d.pop()
                break
        yield l, r
        if max_d and max_d[0] == l:
            max_d.popleft()
        if min_d and min_d[0] == l:
            min_d.popleft()


def longest_calm(values, limit):
    best_i = 0
    best_j = 0
    for l, r in _calm_windows(values, limit):
        if r - l > best_j - best_i:
            best_i = l
            best_j = r
    return best_i, best_j


def count_calm(values, limit):
    total = 0
    for l, r in _calm_windows(values, limit):
        total += r - l
    return total
