import heapq
from collections import Counter


class MedianTracker:
    def __init__(self, prefer_high=False):
        self.prefer_high = prefer_high
        self._lower = []
        self._upper = []
        self._lower_size = 0
        self._upper_size = 0
        self._size = 0
        self._counts = Counter()
        self._delayed_lower = Counter()
        self._delayed_upper = Counter()

    @staticmethod
    def _valid_int(x):
        return isinstance(x, int) and not isinstance(x, bool)

    def _prune_lower(self):
        while self._lower:
            val = -self._lower[0]
            if self._delayed_lower.get(val, 0):
                heapq.heappop(self._lower)
                self._delayed_lower[val] -= 1
                if self._delayed_lower[val] == 0:
                    del self._delayed_lower[val]
            else:
                break

    def _prune_upper(self):
        while self._upper:
            val = self._upper[0]
            if self._delayed_upper.get(val, 0):
                heapq.heappop(self._upper)
                self._delayed_upper[val] -= 1
                if self._delayed_upper[val] == 0:
                    del self._delayed_upper[val]
            else:
                break

    def _rebalance(self):
        self._prune_lower()
        self._prune_upper()
        if self._lower_size > self._upper_size + 1:
            val = -heapq.heappop(self._lower)
            self._lower_size -= 1
            heapq.heappush(self._upper, val)
            self._upper_size += 1
            self._prune_lower()
        elif self._upper_size > self._lower_size:
            val = heapq.heappop(self._upper)
            self._upper_size -= 1
            heapq.heappush(self._lower, -val)
            self._lower_size += 1
            self._prune_upper()

    def add(self, x):
        if not self._valid_int(x):
            raise TypeError("x must be an int")
        self._counts[x] += 1
        self._size += 1
        self._prune_lower()
        if not self._lower or x <= -self._lower[0]:
            heapq.heappush(self._lower, -x)
            self._lower_size += 1
        else:
            heapq.heappush(self._upper, x)
            self._upper_size += 1
        self._rebalance()

    def remove(self, x):
        if not self._valid_int(x):
            raise TypeError("x must be an int")
        if self._counts[x] == 0:
            raise ValueError("not present")
        self._counts[x] -= 1
        if self._counts[x] == 0:
            del self._counts[x]
        self._size -= 1
        self._prune_lower()
        self._prune_upper()
        if self._lower and x <= -self._lower[0]:
            self._delayed_lower[x] += 1
            self._lower_size -= 1
        else:
            self._delayed_upper[x] += 1
            self._upper_size -= 1
        self._rebalance()

    def median(self):
        if self._size == 0:
            raise LookupError("median is undefined for empty tracker")
        self._prune_lower()
        self._prune_upper()
        if self._size % 2 == 1:
            return -self._lower[0]
        if self.prefer_high:
            return self._upper[0]
        return -self._lower[0]

    def __len__(self):
        return self._size
