"""Roman numeral conversion utilities."""

_VALUES = (
    (1000, "M"), (900, "CM"), (500, "D"), (400, "CD"),
    (100, "C"), (90, "XC"), (50, "L"), (40, "XL"),
    (10, "X"), (9, "IX"), (5, "V"), (4, "IV"),
    (1, "I"),
)

_ROMAN_TO_INT = {symbol: value for value, symbol in _VALUES}


def to_roman(n):
    """Return the canonical uppercase Roman numeral for 1 <= n <= 3999."""
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError("n must be an int")
    if n < 1 or n > 3999:
        raise ValueError("n must be between 1 and 3999 inclusive")
    parts = []
    for value, symbol in _VALUES:
        while n >= value:
            parts.append(symbol)
            n -= value
    return "".join(parts)


def from_roman(s):
    """Return the integer for s only if s is exactly canonical."""
    if not isinstance(s, str):
        raise TypeError("s must be a str")
    if s == "":
        raise ValueError("empty string is not a valid Roman numeral")

    total = 0
    i = 0
    length = len(s)
    while i < length:
        cur_value = _ROMAN_TO_INT.get(s[i])
        if cur_value is None:
            raise ValueError(f"invalid character in Roman numeral: {s[i]!r}")
        if i + 1 < length:
            next_value = _ROMAN_TO_INT.get(s[i + 1])
            if next_value is None:
                raise ValueError(
                    f"invalid character in Roman numeral: {s[i + 1]!r}"
                )
            if cur_value < next_value:
                total += next_value - cur_value
                i += 2
                continue
        total += cur_value
        i += 1

    if total < 1 or total > 3999:
        raise ValueError("Roman numeral out of range")
    if to_roman(total) != s:
        raise ValueError("not a canonical Roman numeral")
    return total


def is_roman(s):
    """Return True if s is a canonical Roman numeral, else False."""
    try:
        from_roman(s)
    except (TypeError, ValueError):
        return False
    return True
