def _is_digits(s):
    return s and all('0' <= c <= '9' for c in s)


def expand_field(field, lo, hi):
    if not isinstance(field, str):
        raise ValueError('invalid cron: field must be a string')
    if field == '':
        raise ValueError('invalid cron: empty field')

    values = set()
    for item in field.split(','):
        if item == '':
            raise ValueError('invalid cron: empty item')

        step = 1
        base = item
        if '/' in item:
            base, step_str = item.split('/', 1)
            if not _is_digits(step_str):
                raise ValueError('invalid cron: step must be a positive integer')
            step = int(step_str)
            if step <= 0:
                raise ValueError('invalid cron: step must be >= 1')

        if base == '':
            raise ValueError('invalid cron: malformed item')

        if base == '*':
            start, end = lo, hi
        elif '-' in base:
            a, b = base.split('-', 1)
            if not _is_digits(a) or not _is_digits(b):
                raise ValueError('invalid cron: range bounds must be integers')
            start, end = int(a), int(b)
            if start > end:
                raise ValueError('invalid cron: range start greater than end')
        else:
            if not _is_digits(base):
                raise ValueError('invalid cron: value must be an integer')
            start = int(base)
            end = hi if '/' in item else start

        if not (lo <= start <= hi) or not (lo <= end <= hi):
            raise ValueError('invalid cron: value out of range')

        for v in range(start, end + 1, step):
            values.add(v)

    return sorted(values)


def _parse_expr(expr):
    if not isinstance(expr, str):
        raise ValueError('invalid cron: expression must be a string')
    parts = expr.strip().split()
    if len(parts) != 2:
        raise ValueError('invalid cron: expression must have exactly two fields')
    minutes = expand_field(parts[0], 0, 59)
    hours = expand_field(parts[1], 0, 23)
    return minutes, hours


def cron_matches(expr, hour, minute):
    minutes, hours = _parse_expr(expr)
    if not (0 <= hour <= 23 and 0 <= minute <= 59):
        raise ValueError('invalid cron: time out of range')
    return minute in minutes and hour in hours


def next_match(expr, hour, minute):
    minutes, hours = _parse_expr(expr)
    if not (0 <= hour <= 23 and 0 <= minute <= 59):
        raise ValueError('invalid cron: time out of range')

    if hour in hours:
        for m in minutes:
            if m > minute:
                return (hour, m)

    for h in hours:
        if h > hour:
            return (h, minutes[0])

    return (hours[0], minutes[0])
