from bisect import bisect_right


def _validate_intervals(intervals):
    seq = list(intervals)
    for item in seq:
        if not isinstance(item, tuple) or len(item) != 3:
            raise ValueError("Each interval must be a (start, end, weight) tuple")
        start, end, weight = item
        if isinstance(start, bool) or not isinstance(start, int):
            raise TypeError("start must be an int")
        if isinstance(end, bool) or not isinstance(end, int):
            raise TypeError("end must be an int")
        if isinstance(weight, bool) or not isinstance(weight, int):
            raise TypeError("weight must be an int")
        if start >= end:
            raise ValueError("start must be less than end")
    return seq


def best_schedule(intervals):
    intervals = _validate_intervals(intervals)
    positive = [(s, e, w) for (s, e, w) in intervals if w > 0]
    if not positive:
        return (0, 0)

    positive.sort(key=lambda x: (x[1], x[0]))
    ends = [e for (s, e, w) in positive]
    dp = [(0, 0)]

    for (s, e, w) in positive:
        p = bisect_right(ends, s)
        cand_sum = dp[p][0] + w
        cand_cnt = dp[p][1] + 1
        prev_sum, prev_cnt = dp[-1]
        if cand_sum > prev_sum or (cand_sum == prev_sum and cand_cnt < prev_cnt):
            dp.append((cand_sum, cand_cnt))
        else:
            dp.append((prev_sum, prev_cnt))

    return dp[-1]


def max_parallel(intervals):
    intervals = _validate_intervals(intervals)
    events = []
    for (s, e, w) in intervals:
        events.append((s, 1))
        events.append((e, 0))

    events.sort()
    current = 0
    best = 0
    for (t, kind) in events:
        if kind == 1:
            current += 1
            if current > best:
                best = current
        else:
            current -= 1

    return best
