class Scheduler:
    def __init__(self):
        self._tasks = {}
        self._order = 0
        self._remaining = 0

    def add(self, name, priority, after=()):
        if name in self._tasks:
            raise ValueError(name)

        if isinstance(after, str):
            after = (after,)

        deps = []
        for dep in after:
            if dep not in self._tasks:
                raise KeyError(dep)
            deps.append(dep)

        self._tasks[name] = {
            "priority": priority,
            "order": self._order,
            "deps": tuple(deps),
            "status": "pending",
        }
        self._order += 1
        self._remaining += 1

    def next(self):
        best_name = None
        best_key = None
        for name, info in self._tasks.items():
            if info["status"] != "pending":
                continue
            if any(self._tasks[d]["status"] != "completed" for d in info["deps"]):
                continue
            key = (info["priority"], -info["order"])
            if best_key is None or key > best_key:
                best_key = key
                best_name = name
        if best_name is None:
            return None
        self._tasks[best_name]["status"] = "running"
        return best_name

    def complete(self, name):
        info = self._tasks.get(name)
        if info is None:
            raise KeyError(name)
        if info["status"] != "running":
            raise ValueError(name)
        info["status"] = "completed"
        self._remaining -= 1

    def remaining(self):
        return self._remaining
