from functools import cmp_to_key

_VERSION_RE = re.compile(
    r'^[vV]?'
    r'(0|[1-9][0-9]*)\.'
    r'(0|[1-9][0-9]*)\.'
    r'(0|[1-9][0-9]*)'
    r'(?:-([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?'
    r'(?:\+([A-Za-z0-9-]+(?:\.[A-Za-z0-9-]+)*))?$'
)


def _parse_prerelease(pre_str):
    if pre_str is None:
        return ()
    result = []
    for part in pre_str.split('.'):
        if part.isdigit():
            if len(part) > 1 and part[0] == '0':
                raise ValueError(f"invalid version: leading zero in prerelease identifier {part!r}")
            result.append(int(part))
        else:
            result.append(part)
    return tuple(result)


def parse_version(text):
    if not isinstance(text, str):
        raise ValueError(f"invalid version: {text!r}")
    match = _VERSION_RE.fullmatch(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")
    major = int(match.group(1))
    minor = int(match.group(2))
    patch = int(match.group(3))
    prerelease = _parse_prerelease(match.group(4))
    build = match.group(5)
    return (major, minor, patch, prerelease, build)


def compare_versions(a, b):
    av = parse_version(a)
    bv = parse_version(b)
    for idx in (0, 1, 2):
        if av[idx] != bv[idx]:
            return 1 if av[idx] > bv[idx] else -1
    ap = av[3]
    bp = bv[3]
    if not ap and not bp:
        return 0
    if not ap:
        return 1
    if not bp:
        return -1
    for x, y in zip(ap, bp):
        if isinstance(x, int) and isinstance(y, int):
            if x != y:
                return 1 if x > y else -1
        elif isinstance(x, int):
            return -1
        elif isinstance(y, int):
            return 1
        else:
            if x != y:
                return 1 if x > y else -1
    if len(ap) != len(bp):
        return 1 if len(ap) > len(bp) else -1
    return 0


def sort_versions(versions):
    return sorted(versions, key=cmp_to_key(compare_versions))
