import re
from collections import deque
from decimal import Decimal, ROUND_HALF_EVEN

_PRICE_RE = re.compile(r'^[0-9]+(\.[0-9]{1,4})?$')


def _validate_qty(qty):
    if isinstance(qty, bool) or not isinstance(qty, int):
        raise TypeError("qty must be an int")
    if qty <= 0:
        raise ValueError("qty must be positive")


def _validate_price(price):
    if not isinstance(price, str):
        raise TypeError("price must be a str")
    if not _PRICE_RE.match(price):
        raise ValueError("invalid price format")


class _Lot:
    __slots__ = ('qty', 'price_str', 'price_dec')

    def __init__(self, qty, price_str, price_dec):
        self.qty = qty
        self.price_str = price_str
        self.price_dec = price_dec


class FifoBook:
    def __init__(self):
        self._lots = deque()
        self._holdings = 0
        self._cost_basis_exact = Decimal('0')
        self._realized = Decimal('0.00')

    def buy(self, qty, price):
        _validate_qty(qty)
        _validate_price(price)
        price_dec = Decimal(price)
        self._lots.append(_Lot(qty, price, price_dec))
        self._holdings += qty
        self._cost_basis_exact += price_dec * qty

    def sell(self, qty, price):
        _validate_qty(qty)
        _validate_price(price)
        if qty > self._holdings:
            raise ValueError("insufficient holdings")
        sell_price = Decimal(price)
        remaining = qty
        pnl_exact = Decimal('0')
        consumed_cost = Decimal('0')
        while remaining > 0:
            lot = self._lots[0]
            if lot.qty <= remaining:
                take = lot.qty
                pnl_exact += (sell_price - lot.price_dec) * take
                consumed_cost += lot.price_dec * take
                remaining -= take
                self._holdings -= take
                self._lots.popleft()
            else:
                take = remaining
                pnl_exact += (sell_price - lot.price_dec) * take
                consumed_cost += lot.price_dec * take
                lot.qty -= take
                self._holdings -= take
                remaining = 0
        pnl = pnl_exact.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
        self._realized += pnl
        self._cost_basis_exact -= consumed_cost
        return pnl

    def realized(self):
        return self._realized.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)

    def holdings(self):
        return self._holdings

    def lots(self):
        return [(lot.qty, lot.price_str) for lot in self._lots]

    def cost_basis(self):
        return self._cost_basis_exact.quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
