__all__ = ["satisfies", "max_satisfying"]

_OPERATORS = ("==", "!=", ">=", "<=", "~=", ">", "<")


def _parse_version(version: str) -> tuple[int, ...]:
    s = version.strip()
    if not s:
        raise ValueError("empty version")
    parts = s.split(".")
    result = []
    for part in parts:
        if not part or any(c < "0" or c > "9" for c in part):
            raise ValueError("invalid version")
        result.append(int(part))
    return tuple(result)


def _compare(a: tuple[int, ...], b: tuple[int, ...]) -> int:
    n = max(len(a), len(b))
    for i in range(n):
        av = a[i] if i < len(a) else 0
        bv = b[i] if i < len(b) else 0
        if av != bv:
            return 1 if av > bv else -1
    return 0


def _parse_spec(spec: str):
    s = spec.strip()
    if not s:
        return []
    clauses = []
    for raw in s.split(","):
        clause = raw.strip()
        if not clause:
            raise ValueError("empty clause")
        op = None
        for candidate in _OPERATORS:
            if clause.startswith(candidate):
                op = candidate
                break
        if op is None:
            raise ValueError("missing operator")
        rest = clause[len(op):].strip()
        if not rest:
            raise ValueError("missing version")
        ver = _parse_version(rest)
        if op == "~=" and len(ver) < 2:
            raise ValueError("~= requires multi-component version")
        clauses.append((op, ver))
    return clauses


def _eval_clause(ver: tuple[int, ...], op: str, spec_ver: tuple[int, ...]) -> bool:
    if op == "==":
        return _compare(ver, spec_ver) == 0
    if op == "!=":
        return _compare(ver, spec_ver) != 0
    if op == ">=":
        return _compare(ver, spec_ver) >= 0
    if op == "<=":
        return _compare(ver, spec_ver) <= 0
    if op == ">":
        return _compare(ver, spec_ver) > 0
    if op == "<":
        return _compare(ver, spec_ver) < 0
    if _compare(ver, spec_ver) < 0:
        return False
    upper = spec_ver[:-1]
    upper = upper[:-1] + (upper[-1] + 1,)
    return _compare(ver, upper) < 0


def satisfies(version: str, spec: str) -> bool:
    ver = _parse_version(version)
    clauses = _parse_spec(spec)
    return all(_eval_clause(ver, op, sv) for op, sv in clauses)


def max_satisfying(versions, spec: str):
    clauses = _parse_spec(spec)
    parsed = [(v, _parse_version(v)) for v in versions]
    best_orig = None
    best_ver = None
    for orig, ver in parsed:
        if all(_eval_clause(ver, op, sv) for op, sv in clauses):
            if best_ver is None or _compare(ver, best_ver) > 0:
                best_orig = orig
                best_ver = ver
    return best_orig
