import re


def _class_to_regex(content: str, negated: bool) -> str:
    members = []
    pos = 0
    L = len(content)
    while pos < L:
        ch = content[pos]
        if ch == "\\":
            if pos + 1 < L:
                members.append(("char", content[pos + 1]))
                pos += 2
            else:
                members.append(("char", "\\"))
                pos += 1
        elif ch == "-":
            if pos == 0 or pos == L - 1:
                members.append(("char", "-"))
                pos += 1
            elif members and members[-1][0] == "char":
                lo = members[-1][1]
                nxt = content[pos + 1]
                if nxt != "-" and ord(nxt) >= ord(lo):
                    members[-1] = ("range", (lo, nxt))
                    pos += 2
                else:
                    members.append(("char", "-"))
                    pos += 1
            else:
                members.append(("char", "-"))
                pos += 1
        else:
            members.append(("char", ch))
            pos += 1

    if not members:
        return "[^/]" if negated else "(?!)"

    parts = []
    for typ, val in members:
        if typ == "char":
            if val == "/":
                continue
            parts.append(re.escape(val))
        else:
            lo, hi = val
            if not negated and ord(lo) <= ord("/") <= ord(hi):
                if ord(lo) <= ord("/") - 1:
                    parts.append(
                        f"{re.escape(lo)}-{re.escape(chr(ord('/') - 1))}"
                    )
                if ord(hi) >= ord("/") + 1:
                    parts.append(
                        f"{re.escape(chr(ord('/') + 1))}-{re.escape(hi)}"
                    )
            else:
                parts.append(f"{re.escape(lo)}-{re.escape(hi)}")

    if not parts:
        return "[^/]" if negated else "(?!)"

    if negated:
        return f"[^{''.join(parts)}/]"
    return f"[{''.join(parts)}]"


def glob_to_regex(pattern: str) -> str:
    n = len(pattern)
    i = 0
    out = []
    while i < n:
        ch = pattern[i]
        if ch == "*":
            j = i
            while j < n and pattern[j] == "*":
                j += 1
            run = j - i
            if (
                run == 2
                and (i == 0 or pattern[i - 1] == "/")
                and (j == n or pattern[j] == "/")
            ):
                if j == n:
                    out.append("(?s:.*)")
                    i = j
                else:
                    out.append("(?:[^/]+/)*")
                    i = j + 1
            else:
                out.append("[^/]*")
                i = j
        elif ch == "?":
            out.append("[^/]")
            i += 1
        elif ch == "[":
            k = i + 1
            negated = False
            if k < n and pattern[k] == "!":
                negated = True
                k += 1
            literal_close = False
            if k < n and pattern[k] == "]":
                literal_close = True
                k += 1
            close = k
            while close < n and pattern[close] != "]":
                if pattern[close] == "\\":
                    close += 1
                close += 1
            if close >= n:
                out.append(re.escape("["))
                i += 1
                continue
            content = ("]" if literal_close else "") + pattern[k:close]
            out.append(_class_to_regex(content, negated))
            i = close + 1
        elif ch == "\\":
            if i + 1 < n:
                out.append(re.escape(pattern[i + 1]))
                i += 2
            else:
                out.append(re.escape("\\"))
                i += 1
        else:
            out.append(re.escape(ch))
            i += 1
    return "".join(out)


def glob_match(pattern: str, path: str) -> bool:
    return re.fullmatch(glob_to_regex(pattern), path) is not None
