def validate_stream(events):
    events = list(events)
    seen = set()
    for event in events:
        event_id = event[1]
        if event_id in seen:
            raise ValueError(f"duplicate id: {event_id!r}")
        seen.add(event_id)
    for i in range(1, len(events)):
        prev = events[i - 1]
        curr = events[i]
        if (prev[0], prev[1]) >= (curr[0], curr[1]):
            raise ValueError(f"unsorted at index {i}")
    return None


def diff_events(old, new):
    validate_stream(old)
    validate_stream(new)
    old_by_id = {event[1]: event for event in old}
    new_by_id = {event[1]: event for event in new}
    added = []
    removed = []
    moved = []
    changed = []
    for event in new:
        event_id = event[1]
        if event_id not in old_by_id:
            added.append(event_id)
        else:
            old_event = old_by_id[event_id]
            if old_event[0] != event[0]:
                moved.append(event_id)
            if old_event[2] != event[2]:
                changed.append(event_id)
    for event in old:
        event_id = event[1]
        if event_id not in new_by_id:
            removed.append(event_id)
    return {
        "added": added,
        "removed": removed,
        "moved": moved,
        "changed": changed,
    }


def merge_streams(a, b):
    validate_stream(a)
    validate_stream(b)
    merged = {event[1]: event for event in a}
    merged.update({event[1]: event for event in b})
    return sorted(merged.values(), key=lambda event: (event[0], event[1]))
