class CycleError(ValueError):
    def __init__(self, nodes):
        self.nodes = list(nodes)
        super().__init__(f"cycle involving nodes: {self.nodes}")


def _build_graph(nodes, edges):
    node_set = set(nodes)
    adj = {node: set() for node in node_set}
    preds = {node: set() for node in node_set}
    for before, after in edges:
        if before not in node_set:
            raise ValueError(f"unknown node: {before}")
        if after not in node_set:
            raise ValueError(f"unknown node: {after}")
        adj[before].add(after)
        preds[after].add(before)
    return node_set, adj, preds


def _find_cycle_dependents(node_set, adj):
    index = 0
    indices = {}
    lowlink = {}
    stack = []
    onstack = set()
    sccs = []
    adj_lists = {node: list(adj[node]) for node in node_set}

    for start in node_set:
        if start in indices:
            continue
        indices[start] = index
        lowlink[start] = index
        index += 1
        stack.append(start)
        onstack.add(start)
        work = [(start, 0)]

        while work:
            node, i = work[-1]
            neighbors = adj_lists[node]
            if i < len(neighbors):
                work[-1] = (node, i + 1)
                w = neighbors[i]
                if w not in indices:
                    indices[w] = index
                    lowlink[w] = index
                    index += 1
                    stack.append(w)
                    onstack.add(w)
                    work.append((w, 0))
                elif w in onstack:
                    if indices[w] < lowlink[node]:
                        lowlink[node] = indices[w]
            else:
                work.pop()
                if work:
                    parent = work[-1][0]
                    if lowlink[node] < lowlink[parent]:
                        lowlink[parent] = lowlink[node]
                if lowlink[node] == indices[node]:
                    scc = []
                    while True:
                        w = stack.pop()
                        onstack.remove(w)
                        scc.append(w)
                        if w == node:
                            break
                    sccs.append(scc)

    cycle_nodes = set()
    for scc in sccs:
        if len(scc) > 1:
            cycle_nodes.update(scc)
        elif scc and scc[0] in adj[scc[0]]:
            cycle_nodes.add(scc[0])

    reached = set(cycle_nodes)
    queue = deque(cycle_nodes)
    while queue:
        u = queue.popleft()
        for w in adj[u]:
            if w not in reached:
                reached.add(w)
                queue.append(w)

    return sorted(reached)


def topo_order(nodes, edges):
    node_set, adj, preds = _build_graph(nodes, edges)
    indegree = {node: len(preds[node]) for node in node_set}
    heap = [node for node in node_set if indegree[node] == 0]
    heapq.heapify(heap)
    order = []

    while heap:
        u = heapq.heappop(heap)
        order.append(u)
        for w in adj[u]:
            indegree[w] -= 1
            if indegree[w] == 0:
                heapq.heappush(heap, w)

    if len(order) != len(node_set):
        raise CycleError(_find_cycle_dependents(node_set, adj))

    return order


def layers(nodes, edges):
    node_set, adj, preds = _build_graph(nodes, edges)
    remaining_preds = {node: set(preds[node]) for node in node_set}
    unplaced = set(node_set)
    result = []

    while unplaced:
        layer = [node for node in unplaced if not remaining_preds[node]]
        if not layer:
            raise CycleError(_find_cycle_dependents(node_set, adj))
        layer.sort()
        result.append(layer)
        for u in layer:
            unplaced.remove(u)
            for w in adj[u]:
                remaining_preds[w].discard(u)

    return result
